// Signal Forms (Angular 22 — stable)
import { signalForm, Validators as SV } from '@angular/forms';

loginForm = signalForm({
  email: ['', [SV.required, SV.email]],
  password: ['', [SV.required, SV.minLength(8)]]
});

// Template: no subscribe, no async pipe, no valueChanges
// loginForm.value()   → { email: '...', password: '...' }
// loginForm.valid()   → boolean signal
// loginForm.controls.email.errors()  → ValidationErrors | null

// resource API (generic)
import { resource } from '@angular/core';

userResource = resource({
  request: () => ({ id: this.userId() }),   // re-runs when userId changes
  loader: ({ request }) =>
    fetch(\`/api/users/\${request.id}\`).then(r => r.json()) as Promise<User>
});

// rxResource: loader returns Observable (for RxJS operators)
import { rxResource } from '@angular/core/rxjs-interop';

userResource = rxResource({
  request: () => this.userId(),
  loader: ({ request }) => this.http.get<User>(\`/api/users/\${request}\`).pipe(
    retry({ count: 3, delay: (_, i) => timer(i * 500) })
  )
});

